arguments.command:
for b in rachel monica phoebe joey chandler ross; do
  echo "===== friend/$b (recent Friend-Message) =====";
  git log --format='%H%x09%ci%x09%s' "origin/friend/$b" | while IFS=$'\t' read -r sha ci subject; do
    if git show -s --format='%B' "$sha" | grep -q '^Friend-Message: 1'; then
      ep=$(git show -s --format='%B' "$sha" | sed -n 's/^Episode: //p')
      echo "$sha  $ci  $ep  $subject";
    fi
  done | head -8;
done

for sha in abd98ff04541aa31378b27b167d68f3bcb991c19 37200322bff7b40ed6940ab7cc484adbb401ec00 f66a3c4cf1f83ab2b1cd2efadf39bd7134054443 b18d71896f7a34561a7858ce63c129181f12891e 9378ace155672583edfc8dee9e77d2767a565bac; do
  echo "===== $sha =====";
  git show -s --format='%ci%n%B' "$sha";
done
